function WHudAnimalProfile(model, item)
    local profile, food = Config.AnimalModels[model & 0xffffffff], Config.AnimalFood[item]
    if not profile or not food then return nil end
    if food == 'water' then return profile.drink and profile or nil end
    if food == profile.diet or (food == 'grain' and profile.diet == 'plants') then return profile end
end
